package tokenizer

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import io.circe.Json
import scala.annotation.unchecked.uncheckedVariance

// ============================================================================
// TokenType — sealed hierarchy instead of Python enum
// ============================================================================

sealed abstract class TokenType(val value: String)

object TokenType {
  case object STRING     extends TokenType("string")
  case object NUMERIC    extends TokenType("numeric")
  case object TEMPORAL   extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY     extends TokenType("binary")
  case object NULL       extends TokenType("null")
}

// ============================================================================
// Tokenizable — structural typing expressed as a trait
// ============================================================================

trait Tokenizable {
  def toToken: String
}

// ============================================================================
// Token — immutable value type
// ============================================================================

case class Token(
  value:     String,
  tokenType: TokenType,
  metadata:  Map[String, Any] = Map.empty
) {
  def withMetadata(entries: (String, Any)*): [REDACTED] = metadata ++ entries)
}

// ============================================================================
// MutableTokenBatch — explicit mutability, contrasting with immutable Token
// ============================================================================

class MutableTokenBatch {
  private var _tokens: List[Token]   = List.empty
  private var _processed: Boolean    = false

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens = _tokens :+ token
  }

  def tokens: List[Token] = _tokens

  def markProcessed(): Unit = { _processed = true }
}

// ============================================================================
// Generic containers
//   TokenContainer[+T]  — covariant (producer)
//   TokenSink[-T]       — contravariant (consumer)
//   BivariantHandler[T] — invariant (read–write)
// ============================================================================

class TokenContainer[+T](items: Seq[T]) {
  private val _items: Vector[T] = items.toVector

  def getAll: Vector[T] = _items
  def size: Int          = _items.size

  // @uncheckedVariance mirrors the pattern in Scala's own collections:
  // T is covariant but appears in the contravariant position of a function arg.
  def mapTokens[B](f: (T @uncheckedVariance) => B): List[B] =
    _items.map(f).toList
}

class TokenSink[-T] {
  private var _received: List[Any] = List.empty

  def receive(item: T): Unit = { _received = _received :+ item }

  def drain(): List[Any] = {
    val result = _received
    _received = List.empty
    result
  }
}

class BivariantHandler[T](private var _value: T) {
  def get: T              = _value
  def set(value: T): Unit = { _value = value }

  def transform(f: T => T): T = {
    _value = f(_value)
    _value
  }
}

// ============================================================================
// BaseTokenizer — abstract generic tokenizer
// ============================================================================

abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  /** Lazy, streaming tokenization over any Iterable. */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

// ============================================================================
// StringTokenizer
// ============================================================================

class StringTokenizer(
  val encoding:   String          = "UTF-8",
  val normalizer: String => String = identity
) extends BaseTokenizer[String] {

  def tokenize(value: String): [REDACTED] TokenType.STRING)

  def tokenizeBytes(value: Array[Byte]): [REDACTED] String(value, encoding))
}

// ============================================================================
// NumericTokenizer — fixed-precision formatting via BigDecimal
// ============================================================================

class NumericTokenizer(
  val precision:     Int              = 6,
  val formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[BigDecimal] {

  def tokenize(value: BigDecimal): Token = {
    val str = value
      .setScale(precision, BigDecimal.RoundingMode.HALF_UP)
      .bigDecimal
      .toPlainString
    Token(str, TokenType.NUMERIC, Map("original_type" -> "BigDecimal"))
  }

  def tokenizeInt(value: Int): [REDACTED] TokenType.NUMERIC, Map("original_type" -> "Int"))

  def tokenizeLong(value: Long): [REDACTED] TokenType.NUMERIC, Map("original_type" -> "Long"))

  def tokenizeDouble(value: Double): Token = {
    val str = BigDecimal(value)
      .setScale(precision, BigDecimal.RoundingMode.HALF_UP)
      .bigDecimal
      .toPlainString
    Token(str, TokenType.NUMERIC, Map("original_type" -> "Double"))
  }
}

// ============================================================================
// TemporalTokenizer
// ============================================================================

class TemporalTokenizer(val formatStr: Option[String] = None)
    extends BaseTokenizer[LocalDateTime] {

  private val isoFormatter  = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: LocalDateTime): Token = {
    val fmt = formatStr.fold(isoFormatter)(DateTimeFormatter.ofPattern)
    Token(value.format(fmt), TokenType.TEMPORAL)
  }

  def tokenizeDate(value: LocalDate): Token = {
    val fmt = formatStr.fold(dateFormatter)(DateTimeFormatter.ofPattern)
    Token(value.format(fmt), TokenType.TEMPORAL)
  }
}

// ============================================================================
// UniversalTokenizer — dispatches via overloads + pattern matching
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer   = new StringTokenizer()
  private val numericTokenizer  = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenizeNull: [REDACTED]NULL", TokenType.NULL)

  def tokenize(value: String):        [REDACTED]
  def tokenize(value: Array[Byte]):   [REDACTED]
  def tokenize(value: Int):           [REDACTED]
  def tokenize(value: Long):          [REDACTED]
  def tokenize(value: Double):        [REDACTED]
  def tokenize(value: BigDecimal):    [REDACTED]
  def tokenize(value: LocalDateTime): [REDACTED]
  def tokenize(value: LocalDate):     [REDACTED]
  def tokenize(value: Tokenizable):   [REDACTED] TokenType.STRUCTURED)

  /** Fallback dispatch for untyped values. */
  def tokenizeAny(value: Any): Token = value match {
    case null              => tokenizeNull
    case t: Tokenizable    => tokenize(t)
    case s: String         => tokenize(s)
    case b: Array[Byte]    => tokenize(b)
    case i: Int            => tokenize(i)
    case l: Long           => tokenize(l)
    case d: Double         => tokenize(d)
    case bd: BigDecimal    => tokenize(bd)
    case dt: LocalDateTime => tokenize(dt)
    case ld: LocalDate     => tokenize(ld)
    case other             => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

// ============================================================================
// TokenRegistry — maps keys to containers and runs handlers
// ============================================================================

class TokenRegistry[T] {
  private var _registry: Map[String, TokenContainer[T]] = Map.empty
  private var _handlers: List[T => Option[Token]]       = List.empty

  def register(key: String, container: TokenContainer[T]): Unit =
    _registry = _registry + (key -> container)

  def addHandler(handler: T => Option[Token]): Unit =
    _handlers = _handlers :+ handler

  /** For each item, try handlers in order; return the first match or None. */
  def process(key: String): List[Option[Token]] =
    _registry.get(key).fold(List.empty[Option[Token]]) { container =>
      container.getAll.toList.map { item =>
        _handlers.foldLeft(Option.empty[Token])((acc, h) => acc.orElse(h(item)))
      }
    }
}

// ============================================================================
// TokenFunctor / TokenMonad — functor and monad abstractions
// ============================================================================

class TokenFunctor[T](protected val _value: T) {
  def map[B](f: T => B): TokenFunctor[B]          = new TokenFunctor(f(_value))
  def flatMap[B](f: T => TokenFunctor[B]): TokenFunctor[B] = f(_value)
  def get: T                                       = _value
  def getOrElse(default: T): T                     = if (_value != null) _value else default
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  override def map[B](f: T => B): TokenMonad[B] = new TokenMonad(f(value))

  def ap[B](funcWrapped: TokenMonad[T => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped.get(value))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JsonTokenizer — uses circe for JSON serialisation
// ============================================================================

class JsonTokenizer(val pretty: Boolean = false) {

  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  /** Navigate a dot-separated path and tokenize the value found there. */
  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.").toList

    def navigate(current: Json, remaining: List[String]): Option[Json] =
      remaining match {
        case Nil => Some(current)
        case head :: tail =>
          val next =
            current.asObject.flatMap(_.apply(head)).orElse(
              current.asArray.flatMap { arr =>
                head.toIntOption
                  .filter(i => i >= 0 && i < arr.size)
                  .map(arr(_))
              }
            )
          next.flatMap(navigate(_, tail))
      }

    navigate(value, parts).map(tokenize)
  }
}

// ============================================================================
// WhitespaceTokenizer — splits on whitespace with filtering / normalisation
// ============================================================================

class WhitespaceTokenizer(
  val lowercase:        Boolean      = false,
  val minLength:        Int          = 0,
  val maxLength:        Option[Int]  = None,
  val stripPunctuation: Boolean      = false
) {
  private val punctuationChars: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    val stripped =
      if (stripPunctuation)
        word
          .dropWhile(punctuationChars.contains)
          .reverse
          .dropWhile(punctuationChars.contains)
          .reverse
      else
        word

    val lowered    = if (lowercase) stripped.toLowerCase else stripped
    val truncated  = maxLength.fold(lowered)(lowered.take)

    Option(truncated).filter(s => s.nonEmpty && s.length >= minLength)
  }

  def tokenize(text: String): List[Token] =
    text.split("\\s+").zipWithIndex.toList.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    var currentPos = 0
    text.split("\\s+").flatMap { word =>
      val start = text.indexOf(word, currentPos)
      val end   = start + word.length
      currentPos = end
      processToken(word).map(processed => (processed, start, end))
    }.toList
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// TokenizerBuilder — immutable fluent builder
// ============================================================================

final class TokenizerBuilder[T] private (
  normalizers: List[String => String],
  validators:  List[T => Boolean],
  metaMap:     Map[String, Any]
) {
  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers :+ normalizer, validators, metaMap)

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers, validators :+ validator, metaMap)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers, validators, metaMap ++ entries)

  /** Produce a pure function that validates, normalises, and wraps in Token. */
  def build(): T => Token = { value =>
    validators.foreach { validate =>
      if (!validate(value))
        throw new IllegalArgumentException(s"Validation failed for $value")
    }
    val str = normalizers.foldLeft(value.toString)((s, norm) => norm(s))
    Token(str, TokenType.STRING, metaMap)
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] =
    new TokenizerBuilder[T](List.empty, List.empty, Map.empty)
}
